import json
import base64
import hashlib
from email.mime.multipart import MIMEMultipart
from email.mime.text import MIMEText
from email.mime.base import MIMEBase
from email.utils import formatdate


def validate_request(data):
    """Validate the request schema."""
    if not isinstance(data, dict):
        return False
    required = ['from', 'to', 'subject', 'date', 'message_id', 'body', 'attachments']
    if not all(k in data for k in required):
        return False
    if not isinstance(data['from'], str):
        return False
    if not isinstance(data['to'], list) or not 1 <= len(data['to']) <= 8:
        return False
    if not all(isinstance(a, str) for a in data['to']):
        return False
    if not isinstance(data['subject'], str) or not data['subject']:
        return False
    if not isinstance(data['date'], int):
        return False
    if not isinstance(data['message_id'], str):
        return False
    if not (data['message_id'].startswith('<') and data['message_id'].endswith('>')):
        return False
    if not isinstance(data['body'], str):
        return False
    if not isinstance(data['attachments'], list) or len(data['attachments']) > 8:
        return False
    for att in data['attachments']:
        if not isinstance(att, dict):
            return False
        if set(att.keys()) != {'filename', 'content_type', 'content_b64'}:
            return False
        if not isinstance(att['filename'], str) or not att['filename']:
            return False
        if '/' in att['filename'] or '\\' in att['filename']:
            return False
        if not isinstance(att['content_type'], str) or '/' not in att['content_type']:
            return False
        if not isinstance(att['content_b64'], str):
            return False
    return True


def main():
    """Read JSON request from stdin, build email, emit JSON result to stdout."""
    try:
        data = json.loads(sys.stdin.read())
    except Exception:
        print(json.dumps({"error": "invalid_request"}))
        return

    if not validate_request(data):
        print(json.dumps({"error": "invalid_request"}))
        return

    msg = MIMEMultipart()
    msg.set_boundary('----=_Part_0000_1234567890')
    msg['From'] = data['from']
    msg['To'] = ', '.join(data['to'])
    msg['Subject'] = data['subject']
    msg['Date'] = formatdate(timeval=data['date'], localtime=False, usegmt=True)
    msg['Message-ID'] = data['message_id']
    msg['MIME-Version'] = '1.0'

    if not data['attachments']:
        msg.attach(MIMEText(data['body'], 'plain', 'utf-8'))
    else:
        msg.attach(MIMEText(data['body'], 'plain', 'utf-8'))
        for att in data['attachments']:
            content = base64.b64decode(att['content_b64'])
            att_part = MIMEBase(*att['content_type'].split('/', 1))
            att_part.set_payload(content)
            att_part.add_header('Content-Transfer-Encoding', 'base64')
            att_part.add_header('Content-Disposition', 'attachment', filename=att['filename'])
            msg.attach(att_part)

    message_bytes = msg.as_bytes()
    sha256_hash = hashlib.sha256(message_bytes).hexdigest()
    message_b64 = base64.b64encode(message_bytes).decode('ascii')

    print(json.dumps({
        "format": "eml",
        "message_b64": message_b64,
        "sha256": sha256_hash
    }))


